/**
 * Orbit: moves the object in a circle around its base position.
 *
 * Generated by Pixi Editor (components v1). Plain TypeScript: safe to read, edit and commit.
 */
import { Ticker } from "pixi.js";
import { Component, isEditorPaused } from "../core";

export interface OrbitParams {
  /** Radius of the circle, in pixels. */
  radius: number;
  /** Turns per second. Negative orbits the other way. */
  speed: number;
}

/**
 * Moves the object around its base position in a circle. The object's own position is the centre
 * of the orbit. Paused in Edit mode — switch to Play to preview.
 */
export class Orbit extends Component<OrbitParams> {
  static readonly componentName = "Orbit";
  static readonly defaults: OrbitParams = { radius: 40, speed: 0.5 };

  private time = 0;
  private applied = { x: 0, y: 0 };
  private written = { x: NaN, y: NaN };

  update(): void {
    this.reset();
    if (isEditorPaused()) return;
    this.time += Ticker.shared.deltaMS / 1000;
    const angle = this.time * this.params.speed * Math.PI * 2;
    this.applied = {
      x: Math.cos(angle) * this.params.radius,
      y: Math.sin(angle) * this.params.radius,
    };
    const t = this.target;
    t.x += this.applied.x;
    t.y += this.applied.y;
    this.written = { x: t.x, y: t.y };
  }

  detach(): void {
    this.reset();
  }

  /** Removes last frame's orbit offset, unless something else moved the object since. */
  private reset(): void {
    const t = this.target;
    if (this.applied.x !== 0 && t.x === this.written.x) t.x -= this.applied.x;
    if (this.applied.y !== 0 && t.y === this.written.y) t.y -= this.applied.y;
    this.applied = { x: 0, y: 0 };
  }
}
